Аналогично можно <strong>подружить класс</strong> с методом другого класса или целиком с другим классом:<br><pre><code>class Figure {
    std::vector&lt;Point&gt; points;
    friend class Point;          // весь класс Point — друг
    friend void Drawer::show();  // конкретный метод — друг
};</code></pre>
